from collections import Counter,deque
def comps(gi,conn=8):
    H,W=len(gi),len(gi[0]); seen=set(); cs=[]
    def nbrs(i,j):
        for a in range(-1,2):
            for b in (-1 if conn==8 else 0,0,1):
                if (a,b)!=(0,0) and abs(a)+abs(b)<=1 or True: pass
            yield a,b
    if conn==8: dirs=[(a,b) for a in (-1,0,1) for b in (-1,0,1) if (a,b)!=(0,0)]
    else: dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    for i in range(H):
        for j in range(W):
            if gi[i][j]==2 and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in dirs:
                        p,p2=a+da,b+db
                        if 0<=p<H and 0<=p2<W and gi[p][p2]==2 and (p,p2) not in seen:
                            seen.add((p,p2)); q.append((p,p2))
                cs.append(cells)
    return cs
